def resolve_more_than_half_taxable_year(facts):
    year = facts.get('query_year')
    start = facts.get('shared_home_interval_start_date')
    end = facts.get('shared_home_interval_end_date')
    stated = facts.get('same_principal_abode_more_than_half_taxable_year')

    if start is not None or end is not None:
        if start is not None and not isinstance(start, str):
            raise ValueError('shared_home_interval_start_date must be an explicit ISO calendar date')
        if end is not None and not isinstance(end, str):
            raise ValueError('shared_home_interval_end_date must be an explicit ISO calendar date')
        if start is not None and end is not None:
            if not isinstance(year, int) or isinstance(year, bool):
                return {'value': None, 'open_dependencies': ['query_year is required to apply the more-than-one-half taxable-year condition']}
            overlap = inclusive_year_overlap_days(start, end, year)
            return {'value': 2 * overlap > year_days(year), 'open_dependencies': []}

    if isinstance(stated, bool):
        return {'value': stated, 'open_dependencies': []}

    missing = []
    if start is not None and end is None:
        missing.append('shared_home_interval_end_date is required to resolve the observed shared-home interval')
    elif end is not None and start is None:
        missing.append('shared_home_interval_start_date is required to resolve the observed shared-home interval')
    else:
        missing.append('same_principal_abode_more_than_half_taxable_year or both shared-home interval dates are required')
    return {'value': None, 'open_dependencies': missing}

def qualifying_child(facts):
    stated = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

    abode_result = resolve_more_than_half_taxable_year(facts)
    abode = abode_result.get('value')
    if abode is False:
        return {'value': False, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

    unknown = []
    relationship_ok = facts.get('relationship_requirement_under_section152_c2_met')
    if not isinstance(relationship_ok, bool):
        relationship_ok = None
        relationship = facts.get('relationship_to_taxpayer')
        if isinstance(relationship, str):
            r = relationship.strip().lower().replace('-', '_').replace(' ', '_')
            allowed = ('child', 'son', 'daughter', 'descendant_of_child', 'grandchild', 'brother', 'sister', 'stepbrother', 'stepsister', 'descendant_of_brother', 'descendant_of_sister', 'niece', 'nephew', 'pursuant_to_section_152(c)(2)', 'section_152(c)(2)')
            if r in allowed:
                relationship_ok = True
            else:
                unknown.append('relationship_to_taxpayer does not establish the relationship described in section 152(c)(2)')
        else:
            unknown.append('relationship_to_taxpayer or relationship_requirement_under_section152_c2_met is required')

    age_ok = facts.get('meets_age_requirements_under_section152_c3')
    if not isinstance(age_ok, bool):
        age_ok = None
        child_age = facts.get('individual_age_at_end_of_taxable_year')
        taxpayer_age = facts.get('taxpayer_age_at_end_of_taxable_year')
        if isinstance(child_age, int) and not isinstance(child_age, bool) and isinstance(taxpayer_age, int) and not isinstance(taxpayer_age, bool):
            age_ok = child_age < taxpayer_age and child_age < 25
        else:
            unknown.append('meets_age_requirements_under_section152_c3 or both end-of-year ages are required')

    filed_joint = facts.get('individual_filed_joint_return_with_spouse')
    refund_only = facts.get('joint_return_filed_only_for_refund')
    joint_ok = None
    if isinstance(filed_joint, bool):
        if not filed_joint:
            joint_ok = True
        elif isinstance(refund_only, bool):
            joint_ok = refund_only
        else:
            unknown.append('joint_return_filed_only_for_refund is required when a joint return was filed')
    else:
        unknown.append('individual_filed_joint_return_with_spouse is required')

    if abode is None:
        unknown.extend(abode_result.get('open_dependencies', []))

    conditions = (relationship_ok, abode, age_ok, joint_ok)
    if False in conditions:
        return {'value': False, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}
    if None in conditions:
        return {'value': None, 'used_units': ['u152_c1_pred'], 'open_dependencies': unknown}
    return {'value': True, 'used_units': ['u152_c1_pred'], 'open_dependencies': []}

def surviving_spouse_prior_death_period_applies(facts):
    year = facts.get('query_year')
    if not isinstance(year, int) or isinstance(year, bool):
        return {'value': None, 'used_units': ['u2_a1a_prior_death_pred'], 'open_dependencies': ['query_year is required from the legal query']}

    death_date = facts.get('spouse_date_of_death')
    if death_date is not None:
        if not isinstance(death_date, str):
            raise ValueError('spouse_date_of_death must be an explicit ISO calendar date')
        death_year = calendar_year(death_date)
        return {'value': death_year == year - 1 or death_year == year - 2, 'used_units': ['u2_a1a_prior_death_pred'], 'open_dependencies': []}

    stated = facts.get('spouse_died_during_either_of_two_immediately_preceding_years')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u2_a1a_prior_death_pred'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u2_a1a_prior_death_pred'], 'open_dependencies': ['spouse_date_of_death or the expressly given two-preceding-years condition is required']}

def penal_institution_service_exclusion_applies(facts):
    stated = facts.get('service_performed_by_person_committed_to_penal_institution')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    committed = facts.get('service_performer_committed_to_penal_institution')
    if isinstance(committed, bool):
        return {'value': committed, 'used_units': ['u3306_c21_pred'], 'open_dependencies': []}
    return {'value': None, 'used_units': ['u3306_c21_pred'], 'open_dependencies': ['service_performed_by_person_committed_to_penal_institution or service_performer_committed_to_penal_institution is required']}

def student_service_exclusion_applies(facts):
    stated = facts.get('service_meets_section3306_c10_A_i_conditions')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u3306_c10ai_pred'], 'open_dependencies': []}

    school = facts.get('employer_is_school_college_or_university')
    enrolled = facts.get('employee_enrolled_at_employing_school')
    attending = facts.get('employee_regularly_attending_classes_at_employing_school')
    conditions = (school, enrolled, attending)
    if any(isinstance(value, bool) and not value for value in conditions):
        return {'value': False, 'used_units': ['u3306_c10ai_pred'], 'open_dependencies': []}

    missing = []
    names = ('employer_is_school_college_or_university', 'employee_enrolled_at_employing_school', 'employee_regularly_attending_classes_at_employing_school')
    for index, value in enumerate(conditions):
        if not isinstance(value, bool):
            missing.append(names[index] + ' is required')
    if missing:
        return {'value': None, 'used_units': ['u3306_c10ai_pred'], 'open_dependencies': missing}
    return {'value': True, 'used_units': ['u3306_c10ai_pred'], 'open_dependencies': []}
